import json
# Extract assistant messages with their text and tool_use
def get_text(content):
    if isinstance(content, str): return content
    if isinstance(content, list):
        bits = []
        for c in content:
            if isinstance(c, dict):
                if c.get('type') == 'text':
                    bits.append(c.get('text', ''))
                elif c.get('type') == 'tool_use':
                    name = c.get('name', '?')
                    inp = c.get('input', {})
                    bits.append(f"[TOOL:{name} {json.dumps(inp)[:200]}]")
        return "\n".join(bits)
    return str(content)

